//! The error codes of the protocol and the error type commands fail with.

use std::fmt;

/// The only error codes miniq ever returns.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Code {
    InvalidRequest,
    MissingParameter,
    InvalidParameterValue,
    QueueNameInvalid,
    QueueAlreadyExists,
    QueueDoesNotExist,
    ReceiptHandleInvalid,
    ReceiptHandleExpired,
    UnsupportedOperation,
    LimitExceeded,
}

impl Code {
    pub fn as_str(self) -> &'static str {
        match self {
            Code::InvalidRequest => "InvalidRequest",
            Code::MissingParameter => "MissingParameter",
            Code::InvalidParameterValue => "InvalidParameterValue",
            Code::QueueNameInvalid => "QueueNameInvalid",
            Code::QueueAlreadyExists => "QueueAlreadyExists",
            Code::QueueDoesNotExist => "QueueDoesNotExist",
            Code::ReceiptHandleInvalid => "ReceiptHandleInvalid",
            Code::ReceiptHandleExpired => "ReceiptHandleExpired",
            Code::UnsupportedOperation => "UnsupportedOperation",
            Code::LimitExceeded => "LimitExceeded",
        }
    }
}

/// A failed command: the protocol code plus a message for humans.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Error {
    pub code: Code,
    pub message: String,
}

impl Error {
    pub fn new(code: Code, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }

    pub fn invalid_value(message: impl Into<String>) -> Self {
        Self::new(Code::InvalidParameterValue, message)
    }

    pub fn missing(parameter: &str) -> Self {
        Self::new(
            Code::MissingParameter,
            format!("parameter {parameter} is required"),
        )
    }

    pub fn no_such_queue(name: &str) -> Self {
        Self::new(Code::QueueDoesNotExist, format!("queue {name:?} does not exist"))
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.code.as_str(), self.message)
    }
}

impl std::error::Error for Error {}

pub type Result<T> = std::result::Result<T, Error>;
EOF
cat > src/params.rs <<'EOF'
//! Typed access to the members of a command or of its `Attributes` object.

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, Result};

/// A JSON object whose `null` members have been dropped, because the protocol treats `null` as absent.
pub struct Params(Map<String, Value>);

impl Params {
    pub fn new(mut members: Map<String, Value>) -> Self {
        members.retain(|_, value| !value.is_null());
        Self(members)
    }

    pub fn names(&self) -> impl Iterator<Item = &str> {
        self.0.keys().map(String::as_str)
    }

    /// Fails with `MissingParameter` for the first of `names` that is absent.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| !self.0.contains_key(**name)) {
            Some(name) => Err(Error::missing(name)),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&str>> {
        match self.0.get(name) {
            None => Ok(None),
            Some(Value::String(s)) => Ok(Some(s)),
            Some(_) => Err(Error::invalid_value(format!("{name} must be a string"))),
        }
    }

    pub fn required_string(&self, name: &str) -> Result<&str> {
        self.string(name)?.ok_or_else(|| Error::missing(name))
    }

    pub fn bool(&self, name: &str) -> Result<Option<bool>> {
        match self.0.get(name) {
            None => Ok(None),
            Some(Value::Bool(b)) => Ok(Some(*b)),
            Some(_) => Err(Error::invalid_value(format!("{name} must be a boolean"))),
        }
    }

    pub fn object(&self, name: &str) -> Result<Option<&Map<String, Value>>> {
        match self.0.get(name) {
            None => Ok(None),
            Some(Value::Object(o)) => Ok(Some(o)),
            Some(_) => Err(Error::invalid_value(format!("{name} must be an object"))),
        }
    }

    /// An integer in `range`; `30.0`, `3e1` and `"30"` are not integers.
    pub fn int(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        let Some(value) = self.0.get(name) else {
            return Ok(None);
        };
        let parsed = value
            .as_i64()
            .and_then(|n| u32::try_from(n).ok())
            .filter(|n| range.contains(n));
        match parsed {
            Some(n) => Ok(Some(n)),
            None if value.is_number() => Err(Error::invalid_value(format!(
                "{name} must be an integer from {} to {}",
                range.start(),
                range.end()
            ))),
            None => Err(Error::invalid_value(format!("{name} must be an integer"))),
        }
    }

    pub fn required_int(&self, name: &str, range: RangeInclusive<u32>) -> Result<u32> {
        self.int(name, range)?.ok_or_else(|| Error::missing(name))
    }
}
EOF
