//! A single queue: its attributes and its messages in arrival order.

use std::collections::{BTreeMap, HashMap, HashSet};
use std::rc::Rc;

use crate::error::{Error, Result};
use crate::params::Params;

pub const MAX_QUEUES: usize = 1000;
pub const MAX_MESSAGES: usize = 100_000;
/// A FIFO send repeating a deduplication id accepted less than this many seconds ago is a duplicate.
pub const DEDUPLICATION_WINDOW: u64 = 300;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

impl Attributes {
    fn apply(&mut self, update: &AttributeUpdate, dead_letter: Option<DeadLetter>) {
        self.visibility_timeout = update.visibility_timeout.unwrap_or(self.visibility_timeout);
        self.delay_seconds = update.delay_seconds.unwrap_or(self.delay_seconds);
        self.retention_seconds = update.retention_seconds.unwrap_or(self.retention_seconds);
        self.fifo = update.fifo.unwrap_or(self.fifo);
        self.content_based_deduplication = update
            .content_based_deduplication
            .unwrap_or(self.content_based_deduplication);
        if dead_letter.is_some() {
            self.dead_letter = dead_letter;
        }
    }

    /// Defaults overridden by `update`, as `CreateQueue` builds a queue.
    pub fn from_update(update: &AttributeUpdate, dead_letter: Option<DeadLetter>) -> Self {
        let mut attributes = Self::default();
        attributes.apply(update, dead_letter);
        attributes
    }
}

/// The attributes a request names, each already checked for type and range.
#[derive(Debug, Default)]
pub struct AttributeUpdate {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u32>,
}

impl AttributeUpdate {
    pub fn parse(object: Option<&serde_json::Map<String, serde_json::Value>>) -> Result<Self> {
        let Some(object) = object else {
            return Ok(Self::default());
        };
        let attributes = Params::new(object.clone());
        const NAMES: [&str; 7] = [
            "VisibilityTimeout",
            "DelaySeconds",
            "RetentionSeconds",
            "Fifo",
            "ContentBasedDeduplication",
            "DeadLetterQueue",
            "MaxReceiveCount",
        ];
        if let Some(unknown) = attributes.names().find(|n| !NAMES.contains(n)) {
            return Err(Error::invalid_value(format!("unknown attribute {unknown:?}")));
        }
        Ok(Self {
            visibility_timeout: attributes.int("VisibilityTimeout", 0..=43_200)?,
            delay_seconds: attributes.int("DelaySeconds", 0..=900)?,
            retention_seconds: attributes.int("RetentionSeconds", 60..=1_209_600)?,
            fifo: attributes.bool("Fifo")?,
            content_based_deduplication: attributes.bool("ContentBasedDeduplication")?,
            dead_letter_queue: attributes.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: attributes.int("MaxReceiveCount", 1..=1000)?,
        })
    }

    /// The dead-letter configuration, which must be given completely or not at all.
    pub fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => Ok(Some(DeadLetter {
                queue: queue.clone(),
                max_receive_count,
            })),
            (None, None) => Ok(None),
            _ => Err(Error::invalid_value(
                "DeadLetterQueue and MaxReceiveCount must be given together",
            )),
        }
    }
}

/// Whether `name` follows the queue naming rules.
pub fn is_valid_queue_name(name: &str) -> bool {
    let plain = |s: &str| s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
    match name.strip_suffix(".fifo") {
        Some(stem) => (1..=75).contains(&stem.len()) && plain(stem),
        None => (1..=80).contains(&name.len()) && plain(name),
    }
}

#[derive(Clone, Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    pub group_id: Option<Rc<str>>,
    pub sequence_number: Option<u64>,
    /// The message is hidden while `now < hidden_until`: delayed if `delayed`, else in flight.
    hidden_until: u64,
    delayed: bool,
    /// The receipt handle of the latest delivery.
    handle: Option<u64>,
}

impl Message {
    pub fn new(id: u64, body: String, sent_at: u64, delay: u32, group_id: Option<Rc<str>>) -> Self {
        Self {
            id,
            body,
            sent_at,
            receive_count: 0,
            first_received_at: None,
            group_id,
            sequence_number: None,
            hidden_until: sent_at + u64::from(delay),
            delayed: true,
            handle: None,
        }
    }

    fn is_visible(&self, now: u64) -> bool {
        now >= self.hidden_until
    }

    fn is_in_flight(&self, now: u64) -> bool {
        !self.is_visible(now) && !self.delayed
    }

    /// The message as a dead-letter queue receives it: untouched except for its delivery history.
    fn reset_for_dead_letter(mut self) -> Self {
        self.receive_count = 0;
        self.first_received_at = None;
        self.hidden_until = 0;
        self.delayed = false;
        self.handle = None;
        self.sequence_number = None;
        self
    }
}

#[derive(Debug, PartialEq, Eq)]
pub struct Counts {
    pub visible: usize,
    pub in_flight: usize,
    pub delayed: usize,
}

/// What a `ReceiveMessage` did to a queue.
pub struct Received {
    pub delivered: Vec<Message>,
    /// Messages that exceeded `MaxReceiveCount`, to be appended to the dead-letter queue in order.
    pub dead: Vec<Message>,
}

#[derive(Debug)]
struct Accepted {
    at: u64,
    message_id: u64,
    sequence_number: u64,
}

pub struct Queue {
    pub attributes: Attributes,
    /// Messages keyed by a per-queue arrival counter, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    next_key: u64,
    next_sequence_number: u64,
    /// Latest receipt handle -> arrival key; entries go when their message does.
    handles: HashMap<u64, u64>,
    deduplication: HashMap<String, Accepted>,
    /// A lower bound of the oldest `sent_at` held, so that expiry usually costs nothing.
    oldest_sent_at: u64,
}

impl Queue {
    pub fn new(attributes: Attributes) -> Self {
        Self {
            attributes,
            messages: BTreeMap::new(),
            next_key: 0,
            next_sequence_number: 1,
            handles: HashMap::new(),
            deduplication: HashMap::new(),
            oldest_sent_at: u64::MAX,
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn is_empty(&self) -> bool {
        self.messages.is_empty()
    }

    /// Removes the messages whose retention has run out. Call before reading the queue at `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.attributes.retention_seconds);
        if now < self.oldest_sent_at.saturating_add(retention) {
            return;
        }
        let expired: Vec<u64> = self
            .messages
            .iter()
            .filter(|(_, m)| now >= m.sent_at + retention)
            .map(|(key, _)| *key)
            .collect();
        for key in expired {
            self.remove(key);
        }
        self.oldest_sent_at = self.messages.values().map(|m| m.sent_at).min().unwrap_or(u64::MAX);
    }

    pub fn counts(&self, now: u64) -> Counts {
        let mut counts = Counts { visible: 0, in_flight: 0, delayed: 0 };
        for message in self.messages.values() {
            if message.is_visible(now) {
                counts.visible += 1;
            } else if message.delayed {
                counts.delayed += 1;
            } else {
                counts.in_flight += 1;
            }
        }
        counts
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.handles.clear();
        self.oldest_sent_at = u64::MAX;
    }

    /// Appends `message`, giving it the next sequence number on a FIFO queue.
    pub fn push(&mut self, mut message: Message) -> Option<u64> {
        if self.attributes.fifo {
            message.sequence_number = Some(self.next_sequence_number);
            self.next_sequence_number += 1;
        }
        let sequence_number = message.sequence_number;
        self.oldest_sent_at = self.oldest_sent_at.min(message.sent_at);
        self.messages.insert(self.next_key, message);
        self.next_key += 1;
        sequence_number
    }

    /// The message already accepted under `deduplication_id` less than the window ago, if any.
    pub fn duplicate_of(&self, deduplication_id: &str, now: u64) -> Option<(u64, u64)> {
        let accepted = self.deduplication.get(deduplication_id)?;
        (now - accepted.at < DEDUPLICATION_WINDOW)
            .then_some((accepted.message_id, accepted.sequence_number))
    }

    /// Accepts a FIFO send, recording its deduplication id. Returns the sequence number.
    pub fn accept(&mut self, message: Message, deduplication_id: String, now: u64) -> u64 {
        let message_id = message.id;
        let sequence_number = self.push(message).unwrap_or_default();
        self.deduplication.insert(
            deduplication_id,
            Accepted { at: now, message_id, sequence_number },
        );
        sequence_number
    }

    pub fn push_dead_letter(&mut self, message: Message) {
        self.push(message.reset_for_dead_letter());
    }

    fn remove(&mut self, key: u64) {
        if let Some(handle) = self.messages.remove(&key).and_then(|m| m.handle) {
            self.handles.remove(&handle);
        }
    }

    /// Delivers up to `max` messages, or moves them out when they have been received too often.
    pub fn receive(&mut self, now: u64, max: u32, visibility: u32, next_handle: &mut u64) -> Received {
        let dead_letter_limit = self.attributes.dead_letter.as_ref().map(|d| d.max_receive_count);
        let fifo = self.attributes.fifo;
        let mut blocked_groups: HashSet<Rc<str>> = HashSet::new();
        let mut delivered = Vec::new();
        let mut dead_keys = Vec::new();
        let mut handles_to_drop = Vec::new();
        let mut new_handles = Vec::new();

        for (&key, message) in self.messages.iter_mut() {
            if delivered.len() == max as usize {
                break;
            }
            // A message that stays in the queue holds back its whole group, whatever its state.
            let group_blocked = fifo
                && message
                    .group_id
                    .as_ref()
                    .is_some_and(|g| blocked_groups.contains(g));
            if group_blocked || !message.is_visible(now) {
                if let Some(group) = message.group_id.clone().filter(|_| fifo) {
                    blocked_groups.insert(group);
                }
                continue;
            }
            if dead_letter_limit.is_some_and(|limit| message.receive_count >= limit) {
                dead_keys.push(key);
                continue;
            }
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            message.hidden_until = now + u64::from(visibility);
            message.delayed = false;
            handles_to_drop.extend(message.handle);
            let handle = *next_handle;
            *next_handle += 1;
            message.handle = Some(handle);
            new_handles.push((handle, key));
            if let Some(group) = message.group_id.clone().filter(|_| fifo) {
                blocked_groups.insert(group);
            }
            delivered.push(message.clone());
        }

        for handle in handles_to_drop {
            self.handles.remove(&handle);
        }
        self.handles.extend(new_handles);
        let dead = dead_keys
            .into_iter()
            .filter_map(|key| {
                let message = self.messages.remove(&key)?;
                Some(message)
            })
            .collect();
        Received { delivered, dead }
    }

    /// The key of the message that `handle` was last issued for, if it is in flight at `now`.
    pub fn in_flight_by_handle(&self, handle: u64, now: u64) -> Option<u64> {
        let key = *self.handles.get(&handle)?;
        self.messages.get(&key)?.is_in_flight(now).then_some(key)
    }

    pub fn delete(&mut self, key: u64) {
        self.remove(key);
    }

    pub fn change_visibility(&mut self, key: u64, now: u64, timeout: u32) {
        if let Some(message) = self.messages.get_mut(&key) {
            message.hidden_until = now + u64::from(timeout);
        }
    }
}
