//! The service: the clock, the queues, and the dispatch of one command line to one response.

use std::collections::HashMap;

use serde_json::{json, Map, Value};

use crate::error::{Code, Error, Result};
use crate::params::Params;
use crate::queue::Queue;

/// The result members of a successful command.
pub(crate) type Reply = Result<Map<String, Value>>;

#[derive(Default)]
pub struct Service {
    pub(crate) now: u64,
    pub(crate) queues: HashMap<String, Queue>,
    pub(crate) next_message_id: u64,
    pub(crate) next_receipt_handle: u64,
}

impl Service {
    pub fn new() -> Self {
        Self {
            next_message_id: 1,
            next_receipt_handle: 1,
            ..Self::default()
        }
    }

    /// Runs one input line (without its newline) and returns the response object.
    pub fn handle_line(&mut self, line: &[u8]) -> Value {
        match self.run(line) {
            Ok(mut members) => {
                members.insert("ok".into(), Value::Bool(true));
                Value::Object(members)
            }
            Err(error) => json!({
                "ok": false,
                "error": { "code": error.code.as_str(), "message": error.message },
            }),
        }
    }

    fn run(&mut self, line: &[u8]) -> Reply {
        let invalid = |what: &str| Error::new(Code::InvalidRequest, what.to_owned());
        let text = std::str::from_utf8(line).map_err(|_| invalid("line is not valid UTF-8"))?;
        let Ok(Value::Object(members)) = serde_json::from_str(text) else {
            return Err(invalid("line is not a JSON object"));
        };
        let params = Params::new(members);
        let Some(Value::String(command)) = params.get("Command") else {
            return Err(invalid("Command must be a string"));
        };
        match command.as_str() {
            "CreateQueue" => self.create_queue(&params),
            "SetQueueAttributes" => self.set_queue_attributes(&params),
            "GetQueueAttributes" => self.get_queue_attributes(&params),
            "ListQueues" => self.list_queues(&params),
            "DeleteQueue" => self.delete_queue(&params),
            "PurgeQueue" => self.purge_queue(&params),
            "Tick" => self.tick(&params),
            other => Err(invalid(&format!("unknown command {other:?}"))),
        }
    }

    /// Looks up a queue and drops its messages whose retention has run out.
    pub(crate) fn queue_mut(&mut self, name: &str) -> Result<&mut Queue> {
        let now = self.now;
        let queue = self.queues.get_mut(name).ok_or_else(|| Error::no_such_queue(name))?;
        queue.expire(now);
        Ok(queue)
    }
}

pub(crate) fn no_members() -> Reply {
    Ok(Map::new())
}
