//! `CreateQueue`, `SetQueueAttributes`, `GetQueueAttributes`, `ListQueues`, `DeleteQueue`,
//! `PurgeQueue` and `Tick`.

use serde_json::{json, Map};

use crate::error::{Code, Error, Result};
use crate::params::Params;
use crate::queue::{is_valid_queue_name, AttributeUpdate, Attributes, Queue, MAX_QUEUES};
use crate::service::{no_members, Reply, Service};

impl Service {
    pub(crate) fn create_queue(&mut self, p: &Params) -> Reply {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        if !is_valid_queue_name(name) {
            return Err(Error::new(Code::QueueNameInvalid, format!("{name:?} is not a valid queue name")));
        }
        let update = AttributeUpdate::parse(p.object("Attributes")?)?;
        let fifo = update.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(
                Code::QueueNameInvalid,
                "the .fifo suffix and the Fifo attribute must agree",
            ));
        }
        if update.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::invalid_value("ContentBasedDeduplication needs a FIFO queue"));
        }
        let dead_letter = update.dead_letter()?;
        let attributes = Attributes::from_update(&update, dead_letter);
        if let Some(existing) = self.queues.get(name) {
            return if existing.attributes == attributes {
                no_members()
            } else {
                Err(Error::new(Code::QueueAlreadyExists, format!("queue {name:?} exists with other attributes")))
            };
        }
        if let Some(dead_letter) = &attributes.dead_letter {
            let target = self.queues.get(&dead_letter.queue).ok_or_else(|| Error::no_such_queue(&dead_letter.queue))?;
            if target.attributes.fifo != fifo {
                return Err(Error::invalid_value("the dead-letter queue must be of the same type"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(attributes));
        no_members()
    }

    pub(crate) fn set_queue_attributes(&mut self, p: &Params) -> Reply {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.required_string("QueueName")?;
        let object = p.object("Attributes")?;
        let update = AttributeUpdate::parse(object)?;
        let fifo = self.queue_mut(name)?.attributes.fifo;
        if update.fifo.is_some() {
            return Err(Error::new(Code::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if update.content_based_deduplication == Some(true) && !fifo {
            return Err(Error::invalid_value("ContentBasedDeduplication needs a FIFO queue"));
        }
        let dead_letter = update.dead_letter()?;
        if let Some(dead_letter) = &dead_letter {
            let target = self.queues.get(&dead_letter.queue).ok_or_else(|| Error::no_such_queue(&dead_letter.queue))?;
            if dead_letter.queue == name || target.attributes.fifo != fifo {
                return Err(Error::invalid_value("invalid dead-letter queue"));
            }
        }
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let mut attributes = Attributes::from_update(&update, dead_letter);
        // `from_update` starts from defaults; keep what the request left out.
        let old = &queue.attributes;
        attributes.visibility_timeout = update.visibility_timeout.unwrap_or(old.visibility_timeout);
        attributes.delay_seconds = update.delay_seconds.unwrap_or(old.delay_seconds);
        attributes.retention_seconds = update.retention_seconds.unwrap_or(old.retention_seconds);
        attributes.fifo = old.fifo;
        attributes.content_based_deduplication =
            update.content_based_deduplication.unwrap_or(old.content_based_deduplication);
        if attributes.dead_letter.is_none() {
            attributes.dead_letter = old.dead_letter.clone();
        }
        queue.attributes = attributes;
        queue.expire(now);
        no_members()
    }

    pub(crate) fn get_queue_attributes(&mut self, p: &Params) -> Reply {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let a = &queue.attributes;
        let mut attributes = json!({
            "VisibilityTimeout": a.visibility_timeout,
            "DelaySeconds": a.delay_seconds,
            "RetentionSeconds": a.retention_seconds,
            "Fifo": a.fifo,
            "ContentBasedDeduplication": a.content_based_deduplication,
        });
        if let Some(d) = &a.dead_letter {
            attributes["DeadLetterQueue"] = json!(d.queue);
            attributes["MaxReceiveCount"] = json!(d.max_receive_count);
        }
        let counts = queue.counts(now);
        let mut reply = Map::new();
        reply.insert("Attributes".into(), attributes);
        reply.insert(
            "Counts".into(),
            json!({"Visible": counts.visible, "InFlight": counts.in_flight, "Delayed": counts.delayed}),
        );
        Ok(reply)
    }

    pub(crate) fn list_queues(&mut self, p: &Params) -> Reply {
        let prefix = p.string("Prefix")?.unwrap_or("");
        let mut names: Vec<&String> = self.queues.keys().filter(|n| n.starts_with(prefix)).collect();
        names.sort();
        let mut reply = Map::new();
        reply.insert("QueueNames".into(), json!(names));
        Ok(reply)
    }

    pub(crate) fn delete_queue(&mut self, p: &Params) -> Reply {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        self.queue_mut(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.attributes.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.attributes.dead_letter = None;
            }
        }
