//! `SendMessage`, `ReceiveMessage`, `DeleteMessage` and `ChangeMessageVisibility`.

use std::rc::Rc;

use serde_json::{json, Map, Value};

use crate::error::{Code, Error, Result};
use crate::params::Params;
use crate::queue::{Message, MAX_MESSAGES};
use crate::service::{no_members, Reply, Service};

fn identifier<'a>(p: &'a Params, name: &str) -> Result<Option<&'a str>> {
    let Some(id) = p.string(name)? else {
        return Ok(None);
    };
    let valid = (1..=128).contains(&id.len())
        && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
    if valid {
        Ok(Some(id))
    } else {
        Err(Error::invalid_value(format!("{name} must be 1 to 128 characters from A-Z a-z 0-9 _ -")))
    }
}

/// The number of a receipt handle, if `handle` is exactly `r-<n>` for an `n` issued so far.
fn issued_handle(handle: &str, issued: u64) -> Result<u64> {
    handle
        .strip_prefix("r-")
        .filter(|n| !n.starts_with('0') && n.bytes().all(|b| b.is_ascii_digit()))
        .and_then(|n| n.parse::<u64>().ok())
        .filter(|n| (1..issued).contains(n))
        .ok_or_else(|| Error::new(Code::ReceiptHandleInvalid, format!("receipt handle {handle:?} was never issued")))
}

impl Service {
    pub(crate) fn send_message(&mut self, p: &Params) -> Reply {
        p.require(&["QueueName", "Body"])?;
        let name = p.required_string("QueueName")?;
        let body = p.required_string("Body")?;
        if !(1..=1024).contains(&body.len()) {
            return Err(Error::invalid_value("Body must be 1 to 1024 bytes"));
        }
        let delay = p.int("DelaySeconds", 0..=900)?;
        let group = identifier(p, "GroupId")?;
        let deduplication = identifier(p, "DeduplicationId")?;
        let (now, id) = (self.now, self.next_message_id);
        let queue = self.queue_mut(name)?;
        let fifo = queue.attributes.fifo;
        if (!fifo && (group.is_some() || deduplication.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(Code::UnsupportedOperation, "not supported by this type of queue"));
        }
        let mut reply = Map::new();
        let mut dedup_key = None;
        if fifo {
            let group = group.ok_or_else(|| Error::missing("GroupId"))?;
            let key = match deduplication {
                Some(d) => d,
                None if queue.attributes.content_based_deduplication => body,
                None => return Err(Error::missing("DeduplicationId")),
            };
            if let Some((message_id, sequence)) = queue.duplicate_of(key, now) {
                reply.insert("MessageId".into(), json!(format!("m-{message_id}")));
                reply.insert("SequenceNumber".into(), json!(sequence));
                return Ok(reply);
            }
            dedup_key = Some((key.to_owned(), Rc::<str>::from(group)));
        }
        if queue.len() >= MAX_MESSAGES {
            return Err(Error::new(Code::LimitExceeded, "queue is full"));
        }
        let delay = delay.unwrap_or(queue.attributes.delay_seconds);
        reply.insert("MessageId".into(), json!(format!("m-{id}")));
        match dedup_key {
            Some((key, group)) => {
                let message = Message::new(id, body.to_owned(), now, delay, Some(group));
                reply.insert("SequenceNumber".into(), json!(queue.accept(message, key, now)));
            }
            None => {
                queue.push(Message::new(id, body.to_owned(), now, delay, None));
            }
        }
        self.next_message_id += 1;
        Ok(reply)
    }

    pub(crate) fn receive_message(&mut self, p: &Params) -> Reply {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let max = p.int("MaxMessages", 1..=10)?.unwrap_or(1);
        let timeout = p.int("VisibilityTimeout", 0..=43_200)?;
        let now = self.now;
        let mut next_handle = self.next_receipt_handle;
        let queue = self.queue_mut(name)?;
        let timeout = timeout.unwrap_or(queue.attributes.visibility_timeout);
        let fifo = queue.attributes.fifo;
        let received = queue.receive(now, max, timeout, &mut next_handle);
        let target = queue.attributes.dead_letter.as_ref().map(|d| d.queue.clone());
        self.next_receipt_handle = next_handle;
        if let Some(target) = target {
            let dead_letter_queue = self.queue_mut(&target)?;
            for message in received.dead {
                dead_letter_queue.push_dead_letter(message);
            }
        }
        let first_handle = next_handle - received.delivered.len() as u64;
        let messages: Vec<Value> = received
            .delivered
            .iter()
            .zip(first_handle..)
            .map(|(m, handle)| {
                let mut o = json!({
                    "MessageId": format!("m-{}", m.id),
                    "ReceiptHandle": format!("r-{handle}"),
                    "Body": m.body,
                    "ReceiveCount": m.receive_count,
                    "SentAt": m.sent_at,
                    "FirstReceivedAt": m.first_received_at,
                });
                if fifo {
                    o["GroupId"] = json!(m.group_id.as_deref());
                    o["SequenceNumber"] = json!(m.sequence_number);
                }
                o
            })
            .collect();
        let mut reply = Map::new();
        reply.insert("Messages".into(), Value::Array(messages));
        Ok(reply)
    }

    pub(crate) fn delete_message(&mut self, p: &Params) -> Reply {
        p.require(&["QueueName", "ReceiptHandle"])?;
        let (name, handle) = (p.required_string("QueueName")?, p.required_string("ReceiptHandle")?);
        let (now, issued) = (self.now, self.next_receipt_handle);
        let queue = self.queue_mut(name)?;
        let key = in_flight(queue, handle, issued, now)?;
        queue.delete(key);
        no_members()
    }

    pub(crate) fn change_message_visibility(&mut self, p: &Params) -> Reply {
        p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
        let (name, handle) = (p.required_string("QueueName")?, p.required_string("ReceiptHandle")?);
        let timeout = p.required_int("VisibilityTimeout", 0..=43_200)?;
        let (now, issued) = (self.now, self.next_receipt_handle);
        let queue = self.queue_mut(name)?;
        let key = in_flight(queue, handle, issued, now)?;
        queue.change_visibility(key, now, timeout);
        no_members()
    }
}

fn in_flight(queue: &crate::queue::Queue, handle: &str, issued: u64, now: u64) -> Result<u64> {
    let number = issued_handle(handle, issued)?;
    queue
        .in_flight_by_handle(number, now)
        .ok_or_else(|| Error::new(Code::ReceiptHandleExpired, format!("receipt handle {handle:?} is no longer usable")))
}
