use miniq::Service;
use serde_json::{json, Value};

fn run(s: &mut Service, line: &str) -> Value {
    s.handle_line(line.as_bytes())
}

#[test]
fn send_receive_delete_roundtrip() {
    let mut s = Service::new();
    run(&mut s, r#"{"Command":"CreateQueue","QueueName":"jobs"}"#);
    assert_eq!(run(&mut s, r#"{"Command":"SendMessage","QueueName":"jobs","Body":"x"}"#), json!({"ok":true,"MessageId":"m-1"}));
    let got = run(&mut s, r#"{"Command":"ReceiveMessage","QueueName":"jobs"}"#);
    assert_eq!(got["Messages"][0]["ReceiptHandle"], "r-1");
    assert_eq!(run(&mut s, r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-1"}"#), json!({"ok":true}));
    let again = run(&mut s, r#"{"Command":"DeleteMessage","QueueName":"jobs","ReceiptHandle":"r-1"}"#);
    assert_eq!(again["error"]["code"], "ReceiptHandleExpired");
}

#[test]
fn visibility_timeout_ends_with_tick() {
    let mut s = Service::new();
    run(&mut s, r#"{"Command":"CreateQueue","QueueName":"q"}"#);
    run(&mut s, r#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#);
    run(&mut s, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    run(&mut s, r#"{"Command":"Tick","Seconds":30}"#);
    let got = run(&mut s, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    assert_eq!(got["Messages"][0]["ReceiveCount"], 2);
}

#[test]
fn errors_follow_the_documented_order() {
    let mut s = Service::new();
    assert_eq!(run(&mut s, "nope")["error"]["code"], "InvalidRequest");
    assert_eq!(run(&mut s, r#"{"Command":"PurgeQueue"}"#)["error"]["code"], "MissingParameter");
    assert_eq!(run(&mut s, r#"{"Command":"CreateQueue","QueueName":"a b"}"#)["error"]["code"], "QueueNameInvalid");
    assert_eq!(run(&mut s, r#"{"Command":"Tick","Seconds":30.0}"#)["error"]["code"], "InvalidParameterValue");
    assert_eq!(run(&mut s, r#"{"Command":"PurgeQueue","QueueName":"zz"}"#)["error"]["code"], "QueueDoesNotExist");
}

#[test]
fn fifo_deduplicates_within_window() {
    let mut s = Service::new();
    run(&mut s, r#"{"Command":"CreateQueue","QueueName":"q.fifo","Attributes":{"Fifo":true}}"#);
    let send = r#"{"Command":"SendMessage","QueueName":"q.fifo","Body":"x","GroupId":"g","DeduplicationId":"d"}"#;
    assert_eq!(run(&mut s, send)["SequenceNumber"], 1);
    assert_eq!(run(&mut s, send)["MessageId"], "m-1");
    run(&mut s, r#"{"Command":"Tick","Seconds":300}"#);
    assert_eq!(run(&mut s, send)["MessageId"], "m-2");
}

#[test]
fn dead_letter_after_max_receive_count() {
    let mut s = Service::new();
    run(&mut s, r#"{"Command":"CreateQueue","QueueName":"dlq"}"#);
    run(&mut s, r#"{"Command":"CreateQueue","QueueName":"q","Attributes":{"DeadLetterQueue":"dlq","MaxReceiveCount":1,"VisibilityTimeout":0}}"#);
    run(&mut s, r#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#);
    run(&mut s, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    let empty = run(&mut s, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    assert_eq!(empty["Messages"], json!([]));
    let moved = run(&mut s, r#"{"Command":"ReceiveMessage","QueueName":"dlq"}"#);
    assert_eq!(moved["Messages"][0]["ReceiveCount"], 1);
}
EOF
